pub fn chunk_end(payload: &[u8], offset: usize, size: usize) -> usize {
    let len = payload.len();
    if offset >= len {
        return len;
    }
    let limit = if size > len - offset { len } else { offset + size };
    let e = floor_boundary(payload, limit);
    if e > offset {
        return e;
    }
    let mut j = offset + 1;
    while j < len && !is_boundary(payload, j) {
        j += 1;
    }
    j
}

is_boundary.kernel_code:
pub fn is_boundary(s: &[u8], i: usize) -> bool {
    if i == 0 || i >= s.len() {
        return i <= s.len();
    }
    // not a continuation byte 0b10xx_xxxx
    s[i] < 0x80 || s[i] >= 0xC0
}

printable.kernel_code:
pub fn printable(b: u8) -> bool {
    b >= SPACE && b != DEL
}

floor_boundary.kernel_code:
pub fn floor_boundary(s: &[u8], i: usize) -> usize {
    let mut j = if i > s.len() { s.len() } else { i };
    while j > 0 && !is_boundary(s, j) {
        j -= 1;
    }
    j
}

split_index.kernel_code:
pub fn split_index(remaining: &[u8], width: usize) -> usize {
    let len = remaining.len();
    if len == 0 {
        return 0;
    }
    let mut take = if width < len { width } else { len };
    take = floor_boundary(remaining, take);
    if take == 0 {
        // A first character longer than the width: take it whole.
        take = 1;
        while take < len && !is_boundary(remaining, take) {
            take += 1;
        }
        return take;
    }
    // rfind(' ') in remaining[..take]
    let mut k = take;
    while k > 0 {
        k -= 1;
        if remaining[k] == SPACE {
            if k == 0 {
                return take;
            }
            return k;
        }
    }
    take
}
